  PRIMARY KEY (`schema_id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

INSERT INTO `naac_form_schemas` (`criterion_number`, `version_name`, `is_active`, `schema_json`) VALUES (1, 'v4_university_with_tables', 1, '{\"sections\":[{\"title\":\"1.1 Curriculum Design and Development\",\"metrics\":[{\"id\":\"1.1.1\",\"title\":\"1.1.1: Curricula developed and implemented have relevance to needs\",\"description\":\"Curricula developed and implemented have relevance to the local, national, regional and global developmental needs which is reflected in POs, PSOs and COs.\",\"fields\":[{\"name\":\"qlm_1_1_1_text\",\"label\":\"Description (Max 500 words)\",\"type\":\"textarea\"},{\"name\":\"file_1_1_1\",\"label\":\"Document Upload\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"1.1.2\",\"title\":\"1.1.2: Syllabus revision\",\"description\":\"Percentage of Programmes where syllabus revision was carried out during the last five years.\",\"fields\":[{\"name\":\"qnm_1_1_2_revised\",\"label\":\"Number of programmes where syllabus was revised (Formula Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_1_1_2_total\",\"label\":\"Total number of programmes offered (Formula Denominator)\",\"type\":\"number\"},{\"name\":\"table_1_1_2\",\"label\":\"Data Template: Programmes and Syllabus Revision\",\"type\":\"table\",\"columns\":[{\"name\":\"prog_code\",\"label\":\"Programme Code\",\"type\":\"text\"},{\"name\":\"prog_name\",\"label\":\"Programme Name\",\"type\":\"text\"},{\"name\":\"dept_name\",\"label\":\"Department\",\"type\":\"text\"},{\"name\":\"year_intro\",\"label\":\"Year of Introduction\",\"type\":\"number\"},{\"name\":\"is_revised\",\"label\":\"Revised in last 5 years? (Yes\\/No)\",\"type\":\"text\"},{\"name\":\"year_revision\",\"label\":\"Year of Revision\",\"type\":\"number\"},{\"name\":\"pct_replaced\",\"label\":\"% Content replaced\",\"type\":\"number\"}]},{\"name\":\"file_1_1_2\",\"label\":\"Minutes of relevant Academic Council\\/BOS meeting\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"1.1.3\",\"title\":\"1.1.3: Courses focusing on empl