ode\",\"type\":\"text\"},{\"name\":\"student_name\",\"label\":\"Name of Student\",\"type\":\"text\"},{\"name\":\"project_type\",\"label\":\"Type (Project\\/Internship\\/Field Work)\",\"type\":\"text\"}]},{\"name\":\"file_1_3_4\",\"label\":\"Document Upload\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"1.4 Feedback System\",\"metrics\":[{\"id\":\"1.4.1\",\"title\":\"1.4.1: Structured feedback for design and review of syllabus\",\"description\":\"Structured feedback for design and review of syllabus received from Stakeholders.\",\"fields\":[{\"name\":\"feedback_stakeholders\",\"label\":\"Feedback received from (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"fb_students\",\"label\":\"Students\"},{\"name\":\"fb_teachers\",\"label\":\"Teachers\"},{\"name\":\"fb_employers\",\"label\":\"Employers\"},{\"name\":\"fb_alumni\",\"label\":\"Alumni\"}]},{\"name\":\"file_1_4_1\",\"label\":\"Document Upload (Feedback Reports)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"1.4.2\",\"title\":\"1.4.2: Feedback processes\",\"description\":\"Feedback processes of the institution.\",\"fields\":[{\"name\":\"qlm_1_4_2_process\",\"label\":\"Describe the process of collecting and analyzing feedback\",\"type\":\"textarea\"},{\"name\":\"file_1_4_2\",\"label\":\"Document Upload (Action Taken Report)\",\"type\":\"file\",\"accept\":\".pdf\"}]}]}]}') ON DUPLICATE KEY UPDATE `is_active` = 1;
