try\",\"type\":\"text\"},{\"name\":\"year_sign\",\"label\":\"Year of Signing\",\"type\":\"number\"},{\"name\":\"duration\",\"label\":\"Duration\",\"type\":\"text\"},{\"name\":\"activities_list\",\"label\":\"List of Activities\",\"type\":\"text\"}]},{\"name\":\"file_3_7_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]}]}') ON DUPLICATE KEY UPDATE `is_active` = 1;
INSERT INTO `naac_form_schemas` (`criterion_number`, `version_name`, `is_active`, `schema_json`) VALUES (4, 'v4_university_with_tables', 1, '{\"sections\":[{\"title\":\"4.1 Physical Facilities\",\"metrics\":[{\"id\":\"4.1.1\",\"title\":\"4.1.1: Facilities for teaching-learning\",\"description\":\"The institution has adequate facilities for teaching- learning. viz., classrooms, laboratories, computing equipment, etc.\",\"fields\":[{\"name\":\"qlm_4_1_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_4_1_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.1.2\",\"title\":\"4.1.2: Facilities for sports and cultural activities\",\"description\":\"The institution has adequate facilities for cultural activities, yoga, games (indoor, outdoor) and sports.\",\"fields\":[{\"name\":\"qlm_4_1_2_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_4_1_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.1.3\",\"title\":\"4.1.3: General campus facilities\",\"description\":\"Availability of general campus facilities and overall ambience.\",\"fields\":[{\"name\":\"qlm_4_1_3_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_4_1_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.1.4\",\"title\":\"4.1.4: Expenditure for infrastructure augmentation\",\"description\":\"Average percentage of expenditure excluding salary, for infrastructure augmentation during the last five years.\",\"fields\":[{\"name\":\"qnm_4_1_4_aug\",\"label\":\"Expenditure for infrastructure augmentation (Numerator) (Lakhs)\",\"type\":\"number\"},{\"name\":\"qnm_4_1_4_total\",\"label\":\"Total expenditure excluding salary (Denominator) (Lakhs)\",\"type\":\"number\"},{\"name\":\"table_4_1_4\",\"label\":\"Data Template: Infrastructure Expenditure\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"budget_infra\",\"label\":\"Budget allocated for infra (Lakhs)\",\"type\":\"number\"},{\"name\":\"exp_infra\",\"label\":\"Exp for infra (Lakhs)\",\"type\":\"number\"},{\"name\":\"total_exp\",\"label\":\"Total exp excluding salary (Lakhs)\",\"type\":\"number\"}]},{\"name\":\"file_4_1_4\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"4.2 Library as a Learning Resource\",\"metrics\":[{\"id\":\"4.2.1\",\"title\":\"4.2.1: Library automation (ILMS)\",\"description\":\"Library is automated using Integrated Library Management System (ILMS).\",\"fields\":[{\"name\":\"qlm_4_2_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_4_2_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.2.2\",\"title\":\"4.2.2: E-resources subscription\",\"description\":\"The institution has subscription for the following e-resources.\",\"fields\":[{\"name\":\"eresources_list\",\"label\":\"Options (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"e_journals\",\"label\":\"1. e-journals\"},{\"name\":\"e_shodh\",\"label\":\"2. e-ShodhSindhu\"},{\"name\":\"e_shodhganga\",\"label\":\"3. Shodhganga Membership\"},{\"name\":\"e_books\",\"label\":\"4. e-books\"},{\"name\":\"e_databases\",\"label\":\"5. Databases\"},{\"name\":\"e_remote\",\"label\":\"6. Remote access to e-resources\"}]},{\"name\":\"file_4_2_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.2.3\",\"title\":\"4.2.3: Expenditure on books and journals\",\"description\":\"Average annual expenditure for purchase of books\\/e-books and subscription to journals\\/e-journals during the last five years.\",\"fields\":[{\"name\":\"qnm_4_2_3_exp\",\"label\":\"Annual expenditure on books and journals (Lakhs)\",\"type\":\"number\"},{\"name\":\"table_4_2_3\",\"label\":\"Data Template: Books & Journals Expenditure\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"exp_books\",\"label\":\"Exp on books\\/e-books (Lakhs)\",\"type\":\"number\"},{\"name\":\"exp_journals\",\"label\":\"Exp on journals\\/e-journals (Lakhs)\",\"type\":\"number\"}]},{\"name\":\"file_4_2_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.2.4\",\"title\":\"4.2.4: Library usage per day\",\"description\":\"Percentage per day usage of library by teachers and students.\",\"fields\":[{\"name\":\"qnm_4_2_4_usage\",\"label\":\"Number of teachers and students using library per day (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_4_2_4_total\",\"label\":\"Total number of teachers and students (Denominator)\",\"type\":\"number\"},{\"name\":\"file_4_2_4\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"4.3 IT Infrastructure\",\"metrics\":[{\"id\":\"4.3.1\",\"title\":\"4.3.1: ICT-enabled classrooms\",\"description\":\"Percentage of classrooms and seminar halls with ICT- enabled facilities such as LCD, smart board, Wi-Fi\\/LAN.\",\"fields\":[{\"name\":\"qnm_4_3_1_ict\",\"label\":\"Number of classrooms and seminar halls with ICT facilities (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_4_3_1_total\",\"label\":\"Total number of classrooms and seminar halls (Denominator)\",\"type\":\"number\"},{\"name\":\"table_4_3_1\",\"label\":\"Data Template: ICT Classrooms\",\"type\":\"table\",\"columns\":[{\"name\":\"room_no\",\"label\":\"Room number or Name of classrooms\\/Seminar Hall\",\"type\":\"text\"},{\"name\":\"facility_type\",\"label\":\"Type of ICT facility\",\"type\":\"text\"}]},{\"name\":\"file_4_3_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.3.2\",\"title\":\"4.3.2: IT updates and Wi-Fi\",\"description\":\"Institution has an IT policy, makes appropriate budgetary provisions and updates its IT facilities including the Wi-Fi facility.\",\"fields\":[{\"name\":\"qlm_4_3_2_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_4_3_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.3.3\",\"title\":\"4.3.3: Student - Computer ratio\",\"description\":\"Student \\u2013 Computer ratio.\",\"fields\":[{\"name\":\"qnm_4_3_3_students\",\"label\":\"Total number of students (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_4_3_3_computers\",\"label\":\"Total number of computers in working condition (Denominator)\",\"type\":\"number\"},{\"name\":\"file_4_3_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.3.4\",\"title\":\"4.3.4: Internet Bandwidth\",\"description\":\"Available bandwidth of internet connection in the Institution.\",\"fields\":[{\"name\":\"bandwidth_opts\",\"label\":\"Select available bandwidth (Check one):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"bw_1gbps\",\"label\":\"A. \\u2265 1 GBPS\"},{\"name\":\"bw_500mbps\",\"label\":\"B. 500 MBPS - 1 GBPS\"},{\"name\":\"bw_250mbps\",\"label\":\"C. 250 MBPS - 500 MBPS\"},{\"name\":\"bw_50mbps\",\"label\":\"D. 50 MBPS - 250 MBPS\"},{\"name\":\"bw_less50\",\"label\":\"E. < 50 MBPS\"}]},{\"name\":\"file_4_3_4\",\"label\":\"Supporting Document (Bills\\/Agreements)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.3.5\",\"title\":\"4.3.5: E-content development facilities\",\"description\":\"Institution has the following Facilities for e-content development.\",\"fields\":[{\"name\":\"econtent_facs\",\"label\":\"Available facilities (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"ec_media\",\"label\":\"1. Media centre\"},{\"name\":\"ec_audio\",\"label\":\"2. Audio visual centre\"},{\"name\":\"ec_lecture\",\"label\":\"3. Lecture Capturing System(LCS)\"},{\"name\":\"ec_mixing\",\"label\":\"4. Mixing equipments and softwares for editing\"}]},{\"name\":\"file_4_3_5\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"4.4 Maintenance of Campus Infrastructure\",\"metrics\":[{\"id\":\"4.4.1\",\"title\":\"4.4.1: Expenditure on maintenance\",\"description\":\"Average percentage of expenditure incurred on maintenance of physical facilities and academic support facilities excluding salary.\",\"fields\":[{\"name\":\"qnm_4_4_1_maint\",\"label\":\"Expenditure on maintenance (Numerator) (Lakhs)\",\"type\":\"number\"},{\"name\":\"qnm_4_4_1_total\",\"label\":\"Total expenditure excluding salary (Denominator) (Lakhs)\",\"type\":\"number\"},{\"name\":\"table_4_4_1\",\"label\":\"Data Template: Maintenance Expenditure\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"budget_acad\",\"label\":\"Assigned budget on academic facilities (Lakhs)\",\"type\":\"number\"},{\"name\":\"exp_acad\",\"label\":\"Exp on academic facilities (Lakhs)\",\"type\":\"number\"},{\"name\":\"budget_phys\",\"label\":\"Assigned budget on physical facilities (Lakhs)\",\"type\":\"number\"},{\"name\":\"exp_phys\",\"label\":\"Exp on physical facilities (Lakhs)\",\"type\":\"number\"}]},{\"name\":\"file_4_4_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"4.4.2\",\"title\":\"4.4.2: Maintenance systems and procedures\",\"description\":\"There are established systems and procedures for maintaining and utilizing physical, academic and support facilities.\",\"fields\":[{\"name\":\"qlm_4_4_2_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"qlm_4_4_2_url\",\"label\":\"URL for policy document\",\"type\":\"url\"},{\"name\":\"file_4_4_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]}]}') ON DUPLICATE KEY UPDATE `is_active` = 1;
INSERT INTO `naac_form_schemas` (`criterion_number`, `version_name`, `is_active`, `schema_json`) VALUES (5, 'v5_university_with_tables', 1, '{\"sections\":[{\"title\":\"5.1 Student Support\",\"metrics\":[{\"id\":\"5.1.1\",\"title\":\"5.1.1: Scholarships and Freeships\",\"description\":\"Average percentage of students benefited by scholarships and freeships provided by the institution, Government and non-government bodies.\",\"fields\":[{\"name\":\"qnm_5_1_1_benefited\",\"label\":\"Number of students benefited (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_5_1_1_total\",\"label\":\"Total number of students (Denominator)\",\"type\":\"number\"},{\"name\":\"table_5_1_1\",\"label\":\"Data Template: Scholarships\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"scheme_name\",\"label\":\"Name of the scheme\",\"type\":\"text\"},{\"name\":\"num_benefited\",\"label\":\"Number of students benefiting\",\"type\":\"number\"}]},{\"name\":\"file_5_1_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.1.2\",\"title\":\"5.1.2: Career Counseling and Guidance\",\"description\":\"Average percentage of students benefited by career counseling and guidance for competitive examinations.\",\"fields\":[{\"name\":\"qnm_5_1_2_benefited\",\"label\":\"Number of students benefited (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_5_1_2_total\",\"label\":\"Total number of students (Denominator)\",\"type\":\"number\"},{\"name\":\"table_5_1_2\",\"label\":\"Data Template: Career Counseling\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"scheme_name\",\"label\":\"Name of the scheme\",\"type\":\"text\"},{\"name\":\"num_passed\",\"label\":\"Students passed in competitive exams\",\"type\":\"number\"},{\"name\":\"num_benefited\",\"label\":\"Number of students benefited\",\"type\":\"number\"}]},{\"name\":\"file_5_1_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.1.3\",\"title\":\"5.1.3: Capacity Development and Skills Enhancement\",\"description\":\"Following Capacity development and skills enhancement initiatives are undertaken by the institution.\",\"fields\":[{\"name\":\"skills_opts\",\"label\":\"Initiatives undertaken (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"skill_soft\",\"label\":\"1. Soft skills\"},{\"name\":\"skill_lang\",\"label\":\"2. Language and communication skills\"},{\"name\":\"skill_life\",\"label\":\"3. Life skills (Yoga, physical fitness, health and hygiene)\"},{\"name\":\"skill_tech\",\"label\":\"4. Awareness of trends in technology\"}]},{\"name\":\"table_5_1_3\",\"label\":\"Data Template: Skill Enhancement\",\"type\":\"table\",\"columns\":[{\"name\":\"scheme_name\",\"label\":\"Name of the scheme\",\"type\":\"text\"},{\"name\":\"year_impl\",\"label\":\"Year of implementation\",\"type\":\"number\"},{\"name\":\"num_enrolled\",\"label\":\"Number of students enrolled\",\"type\":\"number\"},{\"name\":\"agencies\",\"label\":\"Name of agencies involved\",\"type\":\"text\"}]},{\"name\":\"file_5_1_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.1.4\",\"title\":\"5.1.4: Student Grievances Redressal\",\"description\":\"The Institution adopts the following for redressal of student grievances including sexual harassment and ragging cases.\",\"fields\":[{\"name\":\"grievance_opts\",\"label\":\"Options (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"gr_guide\",\"label\":\"1. Implementation of guidelines of statutory\\/regulatory bodies\"},{\"name\":\"gr_aware\",\"label\":\"2. Organisation-wide awareness and undertakings on policies\"},{\"name\":\"gr_mech\",\"label\":\"3. Mechanisms for submission of online\\/offline grievances\"},{\"name\":\"gr_timely\",\"label\":\"4. Timely redressal of grievances through appropriate committees\"}]},{\"name\":\"file_5_1_4\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"5.2 Student Progression\",\"metrics\":[{\"id\":\"5.2.1\",\"title\":\"5.2.1: Qualifying in State\\/National\\/International Exams\",\"description\":\"Average percentage of students qualifying in state\\/ national\\/ international level examinations.\",\"fields\":[{\"name\":\"qnm_5_2_1_qual\",\"label\":\"Number of students qualifying (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_5_2_1_appear\",\"label\":\"Number of students appeared (Denominator)\",\"type\":\"number\"},{\"name\":\"table_5_2_1\",\"label\":\"Data Template: Competitive Exams\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"exam_name\",\"label\":\"Exam (NET\\/SLET\\/GATE\\/etc)\",\"type\":\"text\"},{\"name\":\"num_selected\",\"label\":\"Number of students selected\",\"type\":\"number\"}]},{\"name\":\"file_5_2_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.2.2\",\"title\":\"5.2.2: Placement of Outgoing Students\",\"description\":\"Average percentage of placement of outgoing students during the last five years.\",\"fields\":[{\"name\":\"qnm_5_2_2_placed\",\"label\":\"Number of outgoing students placed (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_5_2_2_total\",\"label\":\"Number of outgoing students (Denominator)\",\"type\":\"number\"},{\"name\":\"table_5_2_2\",\"label\":\"Data Template: Placement\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"employer_name\",\"label\":\"Name of the employer with contact\",\"type\":\"text\"},{\"name\":\"num_placed\",\"label\":\"Number of students placed\",\"type\":\"number\"}]},{\"name\":\"file_5_2_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.2.3\",\"title\":\"5.2.3: Progression to Higher Education\",\"description\":\"Percentage of recently-graduated students who have progressed to higher education.\",\"fields\":[{\"name\":\"qnm_5_2_3_prog\",\"label\":\"Number of students progressing to higher education (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_5_2_3_final\",\"label\":\"Total number of final year students (Denominator)\",\"type\":\"number\"},{\"name\":\"table_5_2_3\",\"label\":\"Data Template: Higher Education\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"student_name\",\"label\":\"Name of student enrolling\",\"type\":\"text\"},{\"name\":\"prog_graduated\",\"label\":\"Program graduated from\",\"type\":\"text\"},{\"name\":\"inst_joined\",\"label\":\"Name of institution joined\",\"type\":\"text\"},{\"name\":\"prog_admitted\",\"label\":\"Name of program admitted to\",\"type\":\"text\"}]},{\"name\":\"file_5_2_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"5.3 Student Participation and Activities\",\"metrics\":[{\"id\":\"5.3.1\",\"title\":\"5.3.1: Awards\\/Medals for Sports\\/Cultural Activities\",\"description\":\"Number of awards\\/medals won by students for outstanding performance in sports\\/cultural activities.\",\"fields\":[{\"name\":\"qnm_5_3_1_awards\",\"label\":\"Number of awards\\/medals\",\"type\":\"number\"},{\"name\":\"table_5_3_1\",\"label\":\"Data Template: Sports\\/Cultural Awards\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"award_name\",\"label\":\"Name of the award\\/medal\",\"type\":\"text\"},{\"name\":\"level\",\"label\":\"Level (Inter-university\\/State\\/National\\/Intl)\",\"type\":\"text\"},{\"name\":\"event_name\",\"label\":\"Name of the event\",\"type\":\"text\"}]},{\"name\":\"file_5_3_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.3.2\",\"title\":\"5.3.2: Student Council\",\"description\":\"Presence of Student Council and its activities for institutional development and student welfare.\",\"fields\":[{\"name\":\"qlm_5_3_2_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_5_3_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.3.3\",\"title\":\"5.3.3: Sports and Cultural Events\",\"description\":\"Average number of sports and cultural events \\/ competitions organised by the institution per year.\",\"fields\":[{\"name\":\"qnm_5_3_3_events\",\"label\":\"Number of events organized\",\"type\":\"number\"},{\"name\":\"table_5_3_3\",\"label\":\"Data Template: Events Organized\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"event_name\",\"label\":\"Name of the event \\/ competition\",\"type\":\"text\"}]},{\"name\":\"file_5_3_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"5.4 Alumni Engagement\",\"metrics\":[{\"id\":\"5.4.1\",\"title\":\"5.4.1: Alumni Contribution (QlM)\",\"description\":\"The Alumni Association\\/Chapters (registered and functional) contributes significantly to the development of the institution.\",\"fields\":[{\"name\":\"qlm_5_4_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_5_4_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"5.4.2\",\"title\":\"5.4.2: Alumni contribution (INR in lakhs)\",\"description\":\"Alumni contribution during the last five years (INR in lakhs).\",\"fields\":[{\"name\":\"alumni_contrib_opts\",\"label\":\"Select contribution amount (Check one):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"ac_100\",\"label\":\"A. \\u2265 100 Lakhs\"},{\"name\":\"ac_50\",\"label\":\"B. 50 Lakhs - 100 Lakhs\"},{\"name\":\"ac_20\",\"label\":\"C. 20 Lakhs - 50 Lakhs\"},{\"name\":\"ac_5\",\"label\":\"D. 5 Lakhs - 20 Lakhs\"},{\"name\":\"ac_less5\",\"label\":\"E. < 5 Lakhs\"}]},{\"name\":\"file_5_4_2\",\"label\":\"Supporting Document (Audited Statement)\",\"type\":\"file\",\"accept\":\".pdf\"}]}]}]}') ON DUPLICATE KEY UPDATE `is_active` = 1;
INSERT INTO `naac_form_schemas` (`criterion_number`, `version_name`, `is_active`, `schema_json`) VALUES (6, 'v1_university_with_tables', 1, '{\"sections\":[{\"title\":\"6.1 Institutional Vision and Leadership\",\"metrics\":[{\"id\":\"6.1.1\",\"title\":\"6.1.1: Vision and Mission\",\"description\":\"The institution has a clearly stated vision and mission which are reflected in its academic and administrative governance.\",\"fields\":[{\"name\":\"qlm_6_1_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_1_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.1.2\",\"title\":\"6.1.2: Effective Leadership\",\"description\":\"Effective leadership is reflected in various institutional practices such as decentralization and participative management.\",\"fields\":[{\"name\":\"qlm_6_1_2_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_1_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"6.2 Strategy Development and Deployment\",\"metrics\":[{\"id\":\"6.2.1\",\"title\":\"6.2.1: Strategic Plan Deployment\",\"description\":\"The institutional Strategic plan is effectively deployed.\",\"fields\":[{\"name\":\"qlm_6_2_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_2_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.2.2\",\"title\":\"6.2.2: Functioning of Institutional Bodies\",\"description\":\"Functioning of the institutional bodies is effective and efficient as visible from policies, administrative setup, appointment, service rules, and procedures, etc.\",\"fields\":[{\"name\":\"qlm_6_2_2_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_2_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.2.3\",\"title\":\"6.2.3: Implementation of e-governance\",\"description\":\"Implementation of e-governance in areas of operation.\",\"fields\":[{\"name\":\"egov_opts\",\"label\":\"Areas of e-governance (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"egov_admin\",\"label\":\"1. Administration\"},{\"name\":\"egov_finance\",\"label\":\"2. Finance and Accounts\"},{\"name\":\"egov_student\",\"label\":\"3. Student Admission and Support\"},{\"name\":\"egov_exam\",\"label\":\"4. Examination\"}]},{\"name\":\"table_6_2_3\",\"label\":\"Data Template: e-Governance\",\"type\":\"table\",\"columns\":[{\"name\":\"area\",\"label\":\"Areas of e-governance\",\"type\":\"text\"},{\"name\":\"vendor\",\"label\":\"Name of the Vendor with contact details\",\"type\":\"text\"},{\"name\":\"year_impl\",\"label\":\"Year of implementation\",\"type\":\"number\"}]},{\"name\":\"file_6_2_3\",\"label\":\"Supporting Document (ERP Document\\/Screenshots)\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"6.3 Faculty Empowerment Strategies\",\"metrics\":[{\"id\":\"6.3.1\",\"title\":\"6.3.1: Welfare Measures\",\"description\":\"The institution has effective welfare measures for teaching and non-teaching staff.\",\"fields\":[{\"name\":\"qlm_6_3_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_3_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.3.2\",\"title\":\"6.3.2: Financial Support for Conferences\",\"description\":\"Average percentage of teachers provided with financial support to attend conferences\\/workshops and towards membership fee of professional bodies.\",\"fields\":[{\"name\":\"qnm_6_3_2_supported\",\"label\":\"Number of teachers provided with financial support (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_6_3_2_total\",\"label\":\"Total number of teachers (Denominator)\",\"type\":\"number\"},{\"name\":\"table_6_3_2\",\"label\":\"Data Template: Financial Support\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"teacher_name\",\"label\":\"Name of teacher\",\"type\":\"text\"},{\"name\":\"conf_name\",\"label\":\"Name of conference\\/workshop\",\"type\":\"text\"},{\"name\":\"amount\",\"label\":\"Amount of support (INR)\",\"type\":\"number\"}]},{\"name\":\"file_6_3_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.3.3\",\"title\":\"6.3.3: Professional Development Programs\",\"description\":\"Average number of professional development \\/ administrative training programs organized by the institution for teaching and non-teaching staff.\",\"fields\":[{\"name\":\"qnm_6_3_3_progs\",\"label\":\"Total number of programs organized\",\"type\":\"number\"},{\"name\":\"table_6_3_3\",\"label\":\"Data Template: Development Programs\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"prog_title\",\"label\":\"Title of the professional development program\",\"type\":\"text\"},{\"name\":\"participants\",\"label\":\"No. of participants (Teaching\\/Non-Teaching)\",\"type\":\"number\"}]},{\"name\":\"file_6_3_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.3.4\",\"title\":\"6.3.4: Faculty Development Programmes (FDP)\",\"description\":\"Average percentage of teachers undergoing online\\/face-to-face Faculty Development Programmes (FDP).\",\"fields\":[{\"name\":\"qnm_6_3_4_fdp\",\"label\":\"Number of teachers undergoing FDP (Numerator)\",\"type\":\"number\"},{\"name\":\"qnm_6_3_4_total\",\"label\":\"Total number of teachers (Denominator)\",\"type\":\"number\"},{\"name\":\"table_6_3_4\",\"label\":\"Data Template: FDP Details\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"teacher_name\",\"label\":\"Name of teacher who attended\",\"type\":\"text\"},{\"name\":\"prog_title\",\"label\":\"Title of the program\",\"type\":\"text\"},{\"name\":\"duration\",\"label\":\"Duration (from - to)\",\"type\":\"text\"}]},{\"name\":\"file_6_3_4\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"6.4 Financial Management and Resource Mobilization\",\"metrics\":[{\"id\":\"6.4.1\",\"title\":\"6.4.1: Internal and External Audits\",\"description\":\"Institution conducts internal and external financial audits regularly.\",\"fields\":[{\"name\":\"qlm_6_4_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_4_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.4.2\",\"title\":\"6.4.2: Funds \\/ Grants from Government Bodies\",\"description\":\"Funds \\/ Grants received from government bodies during the last five years for development and maintenance of infrastructure.\",\"fields\":[{\"name\":\"qnm_6_4_2_grants\",\"label\":\"Total Grants received from government bodies (INR in Lakhs)\",\"type\":\"number\"},{\"name\":\"table_6_4_2\",\"label\":\"Data Template: Govt Grants\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"grant_name\",\"label\":\"Name of the government funding agencies\",\"type\":\"text\"},{\"name\":\"funds\",\"label\":\"Funds\\/ Grants received (INR in Lakhs)\",\"type\":\"number\"}]},{\"name\":\"file_6_4_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.4.3\",\"title\":\"6.4.3: Funds \\/ Grants from Non-Government Bodies\",\"description\":\"Funds \\/ Grants received from non-government bodies, individuals, philanthropists during the last five years.\",\"fields\":[{\"name\":\"qnm_6_4_3_grants\",\"label\":\"Total Grants received from non-government bodies (INR in Lakhs)\",\"type\":\"number\"},{\"name\":\"table_6_4_3\",\"label\":\"Data Template: Non-Govt Grants\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"grant_name\",\"label\":\"Name of the non-government funding agencies\\/individuals\",\"type\":\"text\"},{\"name\":\"funds\",\"label\":\"Funds\\/ Grants received (INR in Lakhs)\",\"type\":\"number\"}]},{\"name\":\"file_6_4_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.4.4\",\"title\":\"6.4.4: Institutional strategies for mobilisation of funds\",\"description\":\"Institutional strategies for mobilisation of funds and the optimal utilisation of resources.\",\"fields\":[{\"name\":\"qlm_6_4_4_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_4_4\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"6.5 Internal Quality Assurance System\",\"metrics\":[{\"id\":\"6.5.1\",\"title\":\"6.5.1: IQAC Contribution\",\"description\":\"Internal Quality Assurance Cell (IQAC) has contributed significantly for institutionalizing the quality assurance strategies and processes.\",\"fields\":[{\"name\":\"qlm_6_5_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_5_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.5.2\",\"title\":\"6.5.2: Quality Assurance Initiatives\",\"description\":\"Quality assurance initiatives of the institution.\",\"fields\":[{\"name\":\"qa_opts\",\"label\":\"Initiatives undertaken (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"qa_meeting\",\"label\":\"1. Regular meeting of Internal Quality Assurance Cell (IQAC)\"},{\"name\":\"qa_feedback\",\"label\":\"2. Feedback collected, analyzed and used for improvements\"},{\"name\":\"qa_collab\",\"label\":\"3. Collaborative quality initiatives with other institution(s)\"},{\"name\":\"qa_audit\",\"label\":\"4. Academic Administrative Audit (AAA) and follow-up action\"},{\"name\":\"qa_cert\",\"label\":\"5. ISO \\/ NBA certification or other quality audits\"}]},{\"name\":\"table_6_5_2\",\"label\":\"Data Template: Quality Initiatives\",\"type\":\"table\",\"columns\":[{\"name\":\"year\",\"label\":\"Year\",\"type\":\"number\"},{\"name\":\"initiative_name\",\"label\":\"Name of quality initiative by IQAC\",\"type\":\"text\"},{\"name\":\"duration\",\"label\":\"Duration (from - to)\",\"type\":\"text\"},{\"name\":\"participants\",\"label\":\"Number of participants\",\"type\":\"number\"}]},{\"name\":\"file_6_5_2\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"6.5.3\",\"title\":\"6.5.3: Incremental Improvements\",\"description\":\"Incremental improvements made for the preceding five years with regard to quality.\",\"fields\":[{\"name\":\"qlm_6_5_3_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_6_5_3\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]}]}') ON DUPLICATE KEY UPDATE `is_active` = 1;
INSERT INTO `naac_form_schemas` (`criterion_number`, `version_name`, `is_active`, `schema_json`) VALUES (7, 'v1_university_standard', 1, '{\"sections\":[{\"title\":\"7.1 Institutional Values and Social Responsibilities\",\"metrics\":[{\"id\":\"7.1.1\",\"title\":\"7.1.1: Promotion of Gender Equity\",\"description\":\"Measures initiated by the Institution for the promotion of gender equity during the last five years.\",\"fields\":[{\"name\":\"qlm_7_1_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_7_1_1\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.2\",\"title\":\"7.1.2: Alternate Sources of Energy\",\"description\":\"The Institution has facilities for alternate sources of energy and energy conservation measures.\",\"fields\":[{\"name\":\"energy_opts\",\"label\":\"Facilities available (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"en_solar\",\"label\":\"1. Solar energy\"},{\"name\":\"en_biogas\",\"label\":\"2. Biogas plant\"},{\"name\":\"en_grid\",\"label\":\"3. Wheeling to the Grid\"},{\"name\":\"en_sensor\",\"label\":\"4. Sensor-based energy conservation\"},{\"name\":\"en_led\",\"label\":\"5. Use of LED bulbs\\/ power efficient equipment\"}]},{\"name\":\"file_7_1_2\",\"label\":\"Supporting Document (Geotagged Photographs)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.3\",\"title\":\"7.1.3: Waste Management Facilities\",\"description\":\"Describe the facilities in the Institution for the management of the degradable and non-degradable waste.\",\"fields\":[{\"name\":\"qlm_7_1_3_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_7_1_3\",\"label\":\"Supporting Document (Geotagged Photographs)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.4\",\"title\":\"7.1.4: Water Conservation Facilities\",\"description\":\"Water conservation facilities available in the Institution.\",\"fields\":[{\"name\":\"water_opts\",\"label\":\"Facilities available (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"wa_rain\",\"label\":\"1. Rain water harvesting\"},{\"name\":\"wa_bore\",\"label\":\"2. Borewell \\/Open well recharge\"},{\"name\":\"wa_tank\",\"label\":\"3. Construction of tanks and bunds\"},{\"name\":\"wa_waste\",\"label\":\"4. Waste water recycling\"},{\"name\":\"wa_maint\",\"label\":\"5. Maintenance of water bodies and distribution system in the campus\"}]},{\"name\":\"file_7_1_4\",\"label\":\"Supporting Document (Geotagged Photographs)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.5\",\"title\":\"7.1.5: Green Campus Initiatives\",\"description\":\"Green campus initiatives include restricted entry of automobiles, use of bicycles\\/battery powered vehicles, pedestrian friendly pathways, ban on use of plastic, landscaping.\",\"fields\":[{\"name\":\"green_opts\",\"label\":\"Initiatives available (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"gc_auto\",\"label\":\"1. Restricted entry of automobiles\"},{\"name\":\"gc_battery\",\"label\":\"2. Use of Bicycles\\/ Battery powered vehicles\"},{\"name\":\"gc_path\",\"label\":\"3. Pedestrian Friendly pathways\"},{\"name\":\"gc_plastic\",\"label\":\"4. Ban on use of Plastic\"},{\"name\":\"gc_landscape\",\"label\":\"5. landscaping with trees and plants\"}]},{\"name\":\"file_7_1_5\",\"label\":\"Supporting Document (Geotagged Photographs\\/Circulars)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.6\",\"title\":\"7.1.6: Environment and Energy Audits\",\"description\":\"Quality audits on environment and energy are regularly undertaken by the institution.\",\"fields\":[{\"name\":\"audit_opts\",\"label\":\"Audits undertaken (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"au_green\",\"label\":\"1. Green audit\"},{\"name\":\"au_energy\",\"label\":\"2. Energy audit\"},{\"name\":\"au_env\",\"label\":\"3. Environment audit\"},{\"name\":\"au_clean\",\"label\":\"4. Clean and green campus recognitions\\/awards\"},{\"name\":\"au_beyond\",\"label\":\"5. Beyond the campus environmental promotional activities\"}]},{\"name\":\"file_7_1_6\",\"label\":\"Supporting Document (Audit reports\\/Certificates)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.7\",\"title\":\"7.1.7: Disabled-friendly Environment\",\"description\":\"The Institution has disabled-friendly, barrier free environment.\",\"fields\":[{\"name\":\"disable_opts\",\"label\":\"Facilities available (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"df_built\",\"label\":\"1. Built environment with ramps\\/lifts for easy access to classrooms\"},{\"name\":\"df_wash\",\"label\":\"2. Disabled-friendly washrooms\"},{\"name\":\"df_sign\",\"label\":\"3. Signage including tactile path, lights, display boards and signposts\"},{\"name\":\"df_assist\",\"label\":\"4. Assistive technology and facilities for Divyangjan accessible website, screen-reading software, mechanized equipment\"},{\"name\":\"df_enquiry\",\"label\":\"5. Provision for enquiry and information: Human assistance, reader, scribe, soft copies of reading material, screen reading\"}]},{\"name\":\"file_7_1_7\",\"label\":\"Supporting Document (Geotagged Photographs)\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.8\",\"title\":\"7.1.8: Inclusive Environment\",\"description\":\"Describe the Institutional efforts\\/initiatives in providing an inclusive environment i.e., tolerance and harmony towards cultural, regional, linguistic, communal socioeconomic and other diversities.\",\"fields\":[{\"name\":\"qlm_7_1_8_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_7_1_8\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.9\",\"title\":\"7.1.9: Constitutional Obligations\",\"description\":\"Sensitization of students and employees of the Institution to the constitutional obligations: values, rights, duties and responsibilities of citizens.\",\"fields\":[{\"name\":\"qlm_7_1_9_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_7_1_9\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.10\",\"title\":\"7.1.10: Code of Conduct\",\"description\":\"The Institution has a prescribed code of conduct for students, teachers, administrators and other staff and conducts periodic programmes in this regard.\",\"fields\":[{\"name\":\"conduct_opts\",\"label\":\"Initiatives (Check all that apply):\",\"type\":\"checkbox_group\",\"options\":[{\"name\":\"cc_display\",\"label\":\"1. The Code of Conduct is displayed on the website\"},{\"name\":\"cc_comm\",\"label\":\"2. There is a committee to monitor adherence to the Code of Conduct\"},{\"name\":\"cc_prog\",\"label\":\"3. Institution organizes professional ethics programmes for students, teachers, administrators and other staff\"},{\"name\":\"cc_aware\",\"label\":\"4. Annual awareness programmes on Code of Conduct are organized\"}]},{\"name\":\"file_7_1_10\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]},{\"id\":\"7.1.11\",\"title\":\"7.1.11: Commemorative Days and Events\",\"description\":\"Institution celebrates \\/ organizes national and international commemorative days, events and festivals.\",\"fields\":[{\"name\":\"qlm_7_1_11_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_7_1_11\",\"label\":\"Supporting Document\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"7.2 Best Practices\",\"metrics\":[{\"id\":\"7.2.1\",\"title\":\"7.2.1: Institutional Best Practices\",\"description\":\"Describe two best practices successfully implemented by the Institution as per NAAC format provided in the Manual.\",\"fields\":[{\"name\":\"qlm_7_2_1_text\",\"label\":\"Description of Best Practices\",\"type\":\"textarea\"},{\"name\":\"file_7_2_1\",\"label\":\"Supporting Document \\/ URL\",\"type\":\"file\",\"accept\":\".pdf\"}]}]},{\"title\":\"7.3 Institutional Distinctiveness\",\"metrics\":[{\"id\":\"7.3.1\",\"title\":\"7.3.1: Institutional Distinctiveness\",\"description\":\"Portray the performance of the Institution in one area distinctive to its priority and thrust within 1000 words.\",\"fields\":[{\"name\":\"qlm_7_3_1_text\",\"label\":\"Description\",\"type\":\"textarea\"},{\"name\":\"file_7_3_1\",\"label\":\"Supporting Document \\/ URL\",\"type\":\"file\",\"accept\":\".pdf\"}]}]}]}') ON DUPLICATE KEY UPDATE `is_active` = 1;
